from pathlib import Path
import html,json,subprocess
B=Path(__file__).resolve().parents[1];E=lambda x:html.escape(str(x))
def main():
 p=json.loads((B/'data/round20_pilot_regions.json').read_text());inv=json.loads((B/'data/round20_graphic_inventory.json').read_text());acq=json.loads((B/'data/round20_acquisition_manifest.json').read_text())
 svg=['<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="70 60 670 560"><image href="../sources/round19_image_C.jpg" x="0" y="0" width="978" height="1312"/>']
 for r in p['regions']:
  x,y,w,h=r['box_xywh'];dst=B/f'data/round20_C_{r["region"]}_native.jpg';subprocess.run(['sips','--cropToHeightWidth',str(h),str(w),'--cropOffset',str(y),str(x),str(B/r['image']),'--out',str(dst)],check=True,capture_output=True)
  colour='#55e3cc' if r['boundary_status']=='clear' else '#ffb94e';label=r['region']
  svg.append(f'<a href="round20_C_{label}_native.jpg"><title>{E(r["description"])}</title><rect x="{x}" y="{y}" width="{w}" height="{h}" fill="none" stroke="{colour}" stroke-width="2"/><rect x="{x}" y="{y}" width="36" height="16" fill="#14222c" opacity=".9"/><text x="{x+2}" y="{y+12}" fill="{colour}" font-family="sans-serif" font-size="11">{label}</text></a>')
 svg.append('</svg>');(B/'data/round20_pilot_map.svg').write_text(''.join(svg))
 s='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Инвентарь письма · связанный цикл20</title><style>body{max-width:1400px;margin:auto;padding:30px;background:#f4f1e9;color:#1b2b36;font:18px/1.6 system-ui}a{color:#145981}.note{padding:20px;background:#e7dfcd;border-left:4px solid #786040}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px}figure{margin:0;padding:16px;background:#fff;border:1px solid #ccc}figure img{max-width:100%;height:auto}figure.detail img{width:auto}figcaption{font-size:16px}table{border-collapse:collapse;width:100%;background:#fff;font-size:15px}td,th{padding:10px;border:1px solid #ccc;text-align:left;vertical-align:top}.scroll{overflow:auto}summary{cursor:pointer;font-weight:600}nav{display:flex;gap:18px;flex-wrap:wrap}object{width:100%;min-height:640px}small{display:block}.tag{font-weight:bold;color:#614718}@media(max-width:700px){body{padding:16px}object{min-height:400px}}</style><h1>Инвентарь письма перед чтением слов</h1><p>Связанный цикл20 ·25 октября2026</p><p class="note">Исследованы12 новых фотонаборов и ранее выбранный снимокC. Их индивидуальные чтения и переводы не раскрывались. Выполнены разметка поверхностиC, сравнение8 снимков, фиксация критериев и проверка на4 новых снимках. Основной результат: графический реестр; фонетический алфавит ещё не восстановлен.</p><nav><a href="#map">Карта комплексов</a><a href="#inventory">Реестр</a><a href="#test">Проверка</a><a href="#photos">Весь материал</a><a href="observations/2026-10-25_round20_graphic_inventory.txt">Полный отчёт</a></nav><h2 id="map">Карта видимой поверхности C</h2><p>22 области разметки:21 кандидат на ячейку и1 краевая область;11 границ оценены как достаточно ясные. Зелёные рамки — более ясные, оранжевые — предварительные. Рамки и подписи добавлены поверх фотографии для навигации, не являются древними следами. Нажатие открывает исходный фрагмент.</p><object data="data/round20_pilot_map.svg" type="image/svg+xml"><a href="data/round20_pilot_map.svg">Открыть карту</a></object><p>Разметка не устанавливает направление чтения или границы слов. Возможная более крупная группировка спорной правой полосы сохранена отдельно.</p><h2 id="inventory">Рабочий графический реестр</h2><p>12 предварительных типов и1 спорный кандидат. Это не13 букв. У каждого звучание, слоговая функция и значение пока не определены. Декомпозиция описывает видимую геометрию, не число движений инструмента.</p><div class="grid">'''
 for r in inv['inventory']:
  s+='<figure class="detail"><img src="'+E(r['image_or_crop'])+'" alt="'+E(r['code'])+'"><figcaption><b>'+E(r['code'])+' · '+E(r['description'])+'</b><small>'+E(r['visible_decomposition'])+'</small><small>Примеры: '+E(r['evidence'])+'</small><small class="tag">'+E(r['status'])+'</small><small>'+E(r['uncertainty'])+'</small></figcaption></figure>'
 s+='''</div><h2>Три уровня, которые нельзя смешивать</h2><div class="scroll"><table><tr><th>Уровень</th><th>Что фиксируется</th><th>Что остаётся неизвестным</th></tr><tr><td>След</td><td>Прямая борозда, дуга, угловатый или глубокий след</td><td>Один ли это удар и имеет ли он самостоятельную функцию</td></tr><tr><td>Комплекс</td><td>Рамка, пересечения, внутренние детали, повторы и варианты</td><td>Один ли это знак, сочетание знаков или иная конструкция</td></tr><tr><td>Функция</td><td>Положение и соседство в ячейках</td><td>Буква, слог, слово, число, классификатор или другой элемент</td></tr></table></div><h2 id="test">Проверка на четырёх отложенных снимках</h2><p>Критерии записаны до открытия пикселей A12–A15. Из24 сопоставлений старых6 семейств:1 строгий визуальный кандидат,10 частичных,7 без наблюдаемого совпадения и6 неоцениваемых из-за сохранности. Это не оценка точности алгоритма или статистика родства. Позднейшее уточнение G02a/G02b не использовалось для переписывания проверки.</p><p>Гипотеза повторяемых полей поддержана на A12,A14,A15; A13 недостаточно сохранён. Отдельные углубления занимают сходное положение рядом с меняющимися комплексами. Количественные значения и словесное чтение не назначены.</p><p><a href="data/round20_graphic_inventory.csv">РеестрCSV</a> · <a href="data/round20_pilot_regions.csv">РазметкаCSV</a> · <a href="data/round20_heldout_matches.csv">Все24 сопоставления</a> · <a href="data/round20_preheldout_freeze.json">Фиксация до проверки</a></p><h2 id="photos">Все12 новых фотонаборов</h2><p>Каталожные карточки и переводы не раскрыты. Фотофайл может включать несколько ракурсов или фрагментов; число снимков не считается числом независимых древних предметов. Нажатие открывает полный исходник.</p><div class="grid">'''
 for r in acq:
  stage='Серия для разработки критериев' if int(r['pid'][1:])<12 else 'Отложенная проверочная серия'
  s+=f'<figure><a href="{E(r["image_file"])}"><img loading="lazy" src="{E(r["image_file"])}" style="max-height:580px" alt="{r["label"]}"></a><figcaption><b>{r["label"]}</b><small>{stage}</small></figcaption></figure>'
 s+='</div><p>Источник: опубликованные фотографии CDLI; происхождение и контрольные суммы сохранены в отдельном реестре. Датировка и языковая атрибуция конкретной выборки в этом слое не проверялись. Книга не изменялась.</p></html>'
 (B/'comparison_round20.html').write_text(s);print('Atlas built:22 mapped regions,13 inventory entries,12 complete source images.')
if __name__=='__main__':main()
